### lib/features/project/presentation/providers/project_provider.dart
```dart
import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../../domain/entities/project.dart';
import '../../domain/usecases/get_projects.dart';
import '../../domain/usecases/create_project.dart';

final projectsProvider = StateNotifierProvider<ProjectNotifier, AsyncValue<List<Project>>>((ref) {
  return ProjectNotifier(ref);
});

class ProjectNotifier extends StateNotifier<AsyncValue<List<Project>>> {
  final Ref _ref;

  ProjectNotifier(this._ref) : super(const AsyncValue.loading()) {
    loadProjects();
  }

  Future<void> loadProjects() async {
    state = const AsyncValue.loading();
    try {
      final getProjects = _ref.read(getProjectsUseCaseProvider);
      final projects = await getProjects();
      state = AsyncValue.data(projects);
    } catch (e, st) {
      state = AsyncValue.error(e, st);
    }
  }

  Future<void> createProject(String name, String description) async {
    try {
      final createProject = _ref.read(createProjectUseCaseProvider);
      final newProject = await createProject(name, description);
      state = AsyncValue.data([...state.value ?? [], newProject]);
    } catch (e) {
      rethrow;
    }
  }
}
```

