### src/app/store/service/service.effects.ts
```typescript
import { Injectable, inject } from '@angular/core';
import { Actions, createEffect, ofType } from '@ngrx/effects';
import { ServiceService } from '../../features/service/service.service';
import * as ServiceActions from './service.actions';
import { catchError, map, mergeMap, of } from 'rxjs';

@Injectable()
export class ServiceEffects {
  private actions$ = inject(Actions);
  private serviceService = inject(ServiceService);

  loadServices$ = createEffect(() =>
    this.actions$.pipe(
      ofType(ServiceActions.loadServices),
      mergeMap(() =>
        this.serviceService.getAll().pipe(
          map(services => ServiceActions.loadServicesSuccess({ services })),
          catchError(error => of(ServiceActions.loadServicesFailure({ error: error.message })))
        )
      )
    )
  );

  createService$ = createEffect(() =>
    this.actions$.pipe(
      ofType(ServiceActions.createService),
      mergeMap(({ service }) =>
        this.serviceService.create(service).pipe(
          map(service => ServiceActions.createServiceSuccess({ service })),
          catchError(error => of(ServiceActions.createServiceFailure({ error: error.message })))
        )
      )
    )
  );
}
```

