```typescript
import { Component, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { Store } from '@ngrx/store';
import { MatTableModule } from '@angular/material/table';
import { MatButtonModule } from '@angular/material/button';
import { MatIconModule } from '@angular/material/icon';
import { MatDialog, MatDialogModule } from '@angular/material/dialog';
import { selectServices, selectLoading } from '../../../store/service/service.selectors';
import * as ServiceActions from '../../../store/service/service.actions';
import { ServiceFormComponent } from '../service-form/service-form.component';

@Component({
  selector: 'app-service-list',
  standalone: true,
  imports: [CommonModule, MatTableModule, MatButtonModule, MatIconModule, MatDialogModule],
  template: `
    <div class="container mx-auto p-6">
      <div class="flex justify-between items-center mb-6">
        <h1 class="text-2xl font-bold">Services</h1>
        <button mat-raised-button color="primary" (click)="openCreateDialog()">
          <mat-icon>add</mat-icon> Add Service
        </button>
      </div>

      <mat-table [dataSource]="services()" class="w-full">
        <ng-container matColumnDef="name">
          <mat-header-cell *matHeaderCellDef>Name</mat-header-cell>
          <mat-cell *matCellDef="let item">{{ item.name }}</mat-cell>
        </ng-container>

        <ng-container matColumnDef="status">
          <mat-header-cell *matHeaderCellDef>Status</mat-header-cell>
          <mat-cell *matCellDef="let item">{{ item.status }}</mat-cell>
        </ng-container>

        <ng-container matColumnDef="actions">
          <mat-header-cell *matHeaderCellDef>Actions</mat-header-cell>
          <mat-cell *matCellDef="let item">
            <button mat-icon-button (click)="edit(item)">
              <mat-icon>edit</mat-icon>
            </button>
            <button mat-icon-button color="warn" (click)="delete(item.id)">
              <mat-icon>delete</mat-icon>
            </button>
          </mat-cell>
        </ng-container>

        <mat-header-row *matHeaderRowDef="displayedColumns"></mat-header-row>
        <mat-row *matRowDef="let row; columns: displayedColumns"></mat-row>
      </mat-table>
    </div>
  `
})
export class ServiceListComponent implements OnInit {
  private store = inject(Store);
  private dialog = inject(MatDialog);

  services = this.store.selectSignal(selectServices);
  loading = this.store.selectSignal(selectLoading);
  displayedColumns = ['name', 'status', 'actions'];

  ngOnInit() {
    this.store.dispatch(ServiceActions.loadServices());
  }

  openCreateDialog() {
    this.dialog.open(ServiceFormComponent);
  }

  edit(item: any) {
    this.dialog.open(ServiceFormComponent, { data: item });
  }

  delete(id: string) {
    this.store.dispatch(ServiceActions.deleteService({ id }));
  }
}
```

